CREATE TYPE "BusinessMetricSource" AS ENUM ('OBSERVED','DERIVED','INFERRED','BENCHMARKED','EXPERIMENTAL'); CREATE TYPE "BusinessTimeWindow" AS ENUM ('DAILY','WEEKLY','MONTHLY','QUARTERLY','ROLLING_7_DAYS','ROLLING_30_DAYS','ROLLING_90_DAYS'); CREATE TYPE "GrowthExperimentStatus" AS ENUM ('DRAFT','APPROVED','RUNNING','COMPLETED','CANCELLED'); CREATE TYPE "GrowthExperimentOutcome" AS ENUM ('POSITIVE','NEGATIVE','INCONCLUSIVE','INSUFFICIENT_DATA'); CREATE TYPE "GrowthActionClass" AS ENUM ('READ_ONLY','LOW_RISK_WRITE','REQUIRES_CONFIRMATION','PROHIBITED_AUTONOMOUS');
CREATE TABLE "BusinessIntelligenceProfile" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL UNIQUE,"version" INTEGER NOT NULL DEFAULT 1,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE TABLE "BusinessMetricDefinition" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"metricKey" TEXT NOT NULL,"category" TEXT NOT NULL,"unit" TEXT NOT NULL,"calculationVersion" TEXT NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE); CREATE UNIQUE INDEX "BusinessMetricDefinition_businessId_metricKey_key" ON "BusinessMetricDefinition"("businessId","metricKey"); CREATE UNIQUE INDEX "BusinessMetricDefinition_businessId_id_key" ON "BusinessMetricDefinition"("businessId","id");
CREATE TABLE "BusinessMetricObservation" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"definitionId" TEXT NOT NULL,"source" "BusinessMetricSource" NOT NULL,"sourceEntityType" TEXT NOT NULL,"sourceEntityId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"value" DECIMAL(16,4) NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE,FOREIGN KEY("businessId","definitionId") REFERENCES "BusinessMetricDefinition"("businessId","id") ON DELETE CASCADE); CREATE UNIQUE INDEX "BusinessMetricObservation_businessId_idempotencyKey_key" ON "BusinessMetricObservation"("businessId","idempotencyKey"); CREATE INDEX "BusinessMetricObservation_businessId_definitionId_observedAt_idx" ON "BusinessMetricObservation"("businessId","definitionId","observedAt");
CREATE TABLE "BusinessMetricSnapshot" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"definitionId" TEXT NOT NULL,"window" "BusinessTimeWindow" NOT NULL,"periodStart" TIMESTAMP(3) NOT NULL,"periodEnd" TIMESTAMP(3) NOT NULL,"value" DECIMAL(16,4),"sampleSize" INTEGER NOT NULL,"dataState" TEXT NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"calculationVersion" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE,FOREIGN KEY("businessId","definitionId") REFERENCES "BusinessMetricDefinition"("businessId","id") ON DELETE CASCADE); CREATE UNIQUE INDEX "BusinessMetricSnapshot_unique" ON "BusinessMetricSnapshot"("businessId","definitionId","window","periodStart","calculationVersion");
CREATE TABLE "BusinessInsight" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"insightType" TEXT NOT NULL,"source" "BusinessMetricSource" NOT NULL,"evidence" JSONB NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"explanation" TEXT NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL,"calculationVersion" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE TABLE "BusinessOpportunity" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"opportunityType" TEXT NOT NULL,"evidence" JSONB NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"estimatedImpactRange" JSONB NOT NULL,"constraints" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE); CREATE TABLE "BusinessRiskSignal" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"riskType" TEXT NOT NULL,"evidence" JSONB NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"severity" TEXT NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE TABLE "BusinessBenchmark" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"metricKey" TEXT NOT NULL,"window" "BusinessTimeWindow" NOT NULL,"cohortSize" INTEGER NOT NULL,"privacyThreshold" INTEGER NOT NULL,"aggregateValue" DECIMAL(16,4),"dataState" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE); CREATE TABLE "BusinessGrowthRecommendation" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"recommendationType" TEXT NOT NULL,"evidence" JSONB NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"impactRange" JSONB NOT NULL,"constraints" JSONB NOT NULL,"actionClass" "GrowthActionClass" NOT NULL,"status" TEXT NOT NULL DEFAULT 'PROPOSED',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE TABLE "BusinessGrowthExperiment" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"hypothesis" TEXT NOT NULL,"targetMetric" TEXT NOT NULL,"baselineWindow" "BusinessTimeWindow" NOT NULL,"experimentWindow" "BusinessTimeWindow" NOT NULL,"status" "GrowthExperimentStatus" NOT NULL DEFAULT 'DRAFT',"expectedDirection" TEXT NOT NULL,"constraints" JSONB NOT NULL,"createdBy" TEXT NOT NULL,"approvedBy" TEXT,"startedAt" TIMESTAMP(3),"endedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE); CREATE TABLE "BusinessGrowthExperimentResult" ("id" TEXT PRIMARY KEY,"experimentId" TEXT NOT NULL UNIQUE,"outcome" "GrowthExperimentOutcome" NOT NULL,"baselineValue" DECIMAL(16,4),"experimentValue" DECIMAL(16,4),"sampleSize" INTEGER NOT NULL,"explanation" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("experimentId") REFERENCES "BusinessGrowthExperiment"("id") ON DELETE CASCADE);
CREATE TABLE "BusinessIntelligenceVersion" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"version" INTEGER NOT NULL,"calculationVersion" TEXT NOT NULL,"summary" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE); CREATE UNIQUE INDEX "BusinessIntelligenceVersion_businessId_version_key" ON "BusinessIntelligenceVersion"("businessId","version");
